function getsign(params) {
    var timestamp = Math.floor(new Date().getTime() / 1000);
    var base = "mid=1&userid=0&dfid=0&appid=1005&clientver=0&clienttime=" + timestamp + "&" + params;
    var str = c + a(base) + c;
    return "signature=" + b(str) + "&" + base;
}

var c = "OIlwieks28dk2k092lksi2UIkp";

function a(qs) {
    var params = qs.split('&');
    var obj = {};
    params.forEach(function(p) {
        var kv = p.split('=');
        obj[kv[0]] = kv[1] || '';
    });
    var keys = Object.keys(obj).sort();
    var result = keys.map(function(k) {
        return k + '=' + obj[k];
    });
    return result.join('');
}

function b(str) {
    try {
        var md = java.security.MessageDigest.getInstance("MD5");
        var bytes = new java.lang.String(str).getBytes("UTF-8");
        md.update(bytes);
        var digest = md.digest();
        var hex = "";
        for (var i = 0; i < digest.length; i++) {
            var x = digest[i] & 0xFF;
            if (x < 16) hex += "0";
            hex += x.toString(16);
        }
        return hex;
    } catch(e) {
        return "";
    }
}

